package com.rankedduels;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class RankedDuelsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(RankedDuelsPlugin.class);
		RuneLite.main(args);
	}
}

package com.rankedduels.ui;

import com.rankedduels.DuelState;
import com.rankedduels.RankedDuelsPlugin;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.time.Duration;
import java.time.Instant;

/** Persistent status panel while a duel is pending or in progress. */
public class DuelStatusOverlay extends OverlayPanel
{
    private final RankedDuelsPlugin plugin;

    @Inject
    public DuelStatusOverlay(RankedDuelsPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        DuelState state = plugin.getState();
        // The fight banner covers PENDING_FIGHT and FIGHTING; this panel
        // only handles the waiting-for-answer state.
        if (state != DuelState.CHALLENGE_SENT)
        {
            return null;
        }

        panelComponent.getChildren().add(TitleComponent.builder()
            .text("Ranked Duel")
            .color(new Color(0xB3, 0x00, 0x00))
            .build());

        switch (state)
        {
            case CHALLENGE_SENT:
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Waiting for").right(plugin.getOpponentName()).build());
                if (plugin.getWinDelta() != 0 || plugin.getLossDelta() != 0)
                {
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Win " + RankedDuelsPlugin.formatDelta(plugin.getWinDelta()))
                        .leftColor(new Color(0x6F, 0xA8, 0x5E))
                        .right("Lose " + RankedDuelsPlugin.formatDelta(plugin.getLossDelta()))
                        .rightColor(new Color(0xC7, 0x5B, 0x52))
                        .build());
                }
                break;
            case PENDING_FIGHT:
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Confirmed vs").right(plugin.getOpponentName()).build());
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("First hit starts the duel").right("").build());
                break;
            case FIGHTING:
                panelComponent.getChildren().add(LineComponent.builder()
                    .left("Fighting").right(plugin.getOpponentName()).build());
                if (plugin.getFightStartedAt() != null)
                {
                    long secs = Duration.between(plugin.getFightStartedAt(), Instant.now()).getSeconds();
                    panelComponent.getChildren().add(LineComponent.builder()
                        .left("Duration").right(secs + "s").build());
                }
                break;
            default:
                break;
        }
        return super.render(graphics);
    }
}

package com.rankedduels.ui;

import com.rankedduels.DuelState;
import com.rankedduels.RankedDuelsPlugin;
import com.rankedduels.api.ChallengeInfo;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;

/**
 * Accept / Decline prompt for incoming challenges.
 *
 * Clicks: the mouse listener is registered for the plugin's whole lifetime
 * (registerClicks/unregisterClicks from the plugin), not per-frame - the
 * old per-render registration was unreliable. Hotkeys (default Y / N)
 * provide a second, always-working path and are shown on the buttons.
 */
public class ChallengePromptOverlay extends Overlay
{
    private static final int WIDTH = 280;
    private static final int HEIGHT = 122;

    private static final Color BG = new Color(16, 13, 10, 240);
    private static final Color GOLD = new Color(0xC9, 0xA2, 0x27);
    private static final Color PARCH = new Color(0xE9, 0xDC, 0xB8);
    private static final Color WIN = new Color(0x6F, 0xA8, 0x5E);
    private static final Color LOSS = new Color(0xC7, 0x5B, 0x52);
    private static final Color BTN_ACCEPT = new Color(0x1F, 0x6B, 0x2A);
    private static final Color BTN_DECLINE = new Color(0x7A, 0x1F, 0x1F);

    private final RankedDuelsPlugin plugin;
    private final MouseManager mouseManager;

    private volatile Rectangle acceptBounds = new Rectangle();
    private volatile Rectangle declineBounds = new Rectangle();

    private final MouseAdapter mouseListener = new MouseAdapter()
    {
        @Override
        public MouseEvent mousePressed(MouseEvent e)
        {
            if (plugin.getState() != DuelState.CHALLENGE_RECEIVED || e.getButton() != MouseEvent.BUTTON1)
            {
                return e;
            }
            if (acceptBounds.contains(e.getPoint()))
            {
                plugin.acceptChallenge();
                e.consume();
            }
            else if (declineBounds.contains(e.getPoint()))
            {
                plugin.declineChallenge();
                e.consume();
            }
            return e;
        }
    };

    @Inject
    public ChallengePromptOverlay(RankedDuelsPlugin plugin, MouseManager mouseManager)
    {
        this.plugin = plugin;
        this.mouseManager = mouseManager;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    /** Called once from the plugin's startUp. */
    public void registerClicks()
    {
        mouseManager.registerMouseListener(mouseListener);
    }

    /** Called once from the plugin's shutDown. */
    public void unregisterClicks()
    {
        mouseManager.unregisterMouseListener(mouseListener);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        ChallengeInfo ch = plugin.getPendingChallenge();
        if (plugin.getState() != DuelState.CHALLENGE_RECEIVED || ch == null)
        {
            acceptBounds = new Rectangle();
            declineBounds = new Rectangle();
            return null;
        }

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        // Panel
        RoundRectangle2D panel = new RoundRectangle2D.Float(0, 0, WIDTH, HEIGHT, 10, 10);
        g.setColor(BG);
        g.fill(panel);
        g.setColor(GOLD);
        g.setStroke(new BasicStroke(1.2f));
        g.draw(panel);

        // Title
        g.setFont(new Font(Font.SERIF, Font.BOLD, 15));
        g.setColor(GOLD);
        g.drawString("Ranked Duel Challenge", 14, 24);

        // Who + rating
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 13));
        g.setColor(PARCH);
        String line = ch.getChallengerName()
            + (ch.getChallengerRating() > 0 ? "  (" + ch.getChallengerRating() + ")" : "");
        g.drawString(line, 14, 46);

        // Stakes
        g.setFont(new Font(Font.MONOSPACED, Font.BOLD, 12));
        g.setColor(WIN);
        String winText = "Win " + RankedDuelsPlugin.formatDelta(ch.getWinDelta());
        g.drawString(winText, 14, 66);
        g.setColor(LOSS);
        g.drawString("Lose " + RankedDuelsPlugin.formatDelta(ch.getLossDelta()),
            22 + g.getFontMetrics().stringWidth(winText), 66);

        // Buttons with hotkey hints
        Rectangle a = drawButton(g, 14, 80, 120, 28, "Accept  [Y]", BTN_ACCEPT);
        Rectangle d = drawButton(g, 146, 80, 120, 28, "Decline  [N]", BTN_DECLINE);

        // Convert to canvas coordinates for hit testing
        Rectangle bounds = getBounds();
        if (bounds != null)
        {
            a.translate(bounds.x, bounds.y);
            d.translate(bounds.x, bounds.y);
        }
        acceptBounds = a;
        declineBounds = d;

        return new Dimension(WIDTH, HEIGHT);
    }

    private Rectangle drawButton(Graphics2D g, int x, int y, int w, int h, String label, Color color)
    {
        g.setColor(color);
        g.fillRoundRect(x, y, w, h, 6, 6);
        g.setColor(new Color(255, 255, 255, 40));
        g.drawRoundRect(x, y, w, h, 6, 6);
        g.setColor(Color.WHITE);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        FontMetrics fm = g.getFontMetrics();
        g.drawString(label, x + (w - fm.stringWidth(label)) / 2, y + (h + fm.getAscent() - fm.getDescent()) / 2);
        return new Rectangle(x, y, w, h);
    }
}

package com.rankedduels.ui;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.rankedduels.DuelState;
import com.rankedduels.RankedDuelsConfig;
import com.rankedduels.api.ApiClient;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.*;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import java.awt.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Supplier;

/**
 * Ranked Duels side panel. Fixed to the plugin-panel width (no horizontal
 * scrolling), vertical scroll only when needed, contextual Cancel button
 * while a duel is pending or live.
 */
@Singleton
public class RankedDuelsPanel extends PluginPanel
{
    private static final Color GOLD = new Color(0xC9, 0xA2, 0x27);
    private static final Color HITSPLAT = new Color(0xC0, 0x28, 0x1C);
    private static final Color WIN = new Color(0x6F, 0xA8, 0x5E);
    private static final Color LOSS = new Color(0xC7, 0x5B, 0x52);
    private static final Color DIM = new Color(0xA9, 0x9C, 0x78);
    private static final Color CARD = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color CARD_EDGE = new Color(0x33, 0x2B, 0x1F);

    private final ApiClient api;
    private final RankedDuelsConfig config;
    private final ScheduledExecutorService executor;

    private final JPanel content = new JPanel();
    private final JLabel statusLabel = new JLabel(" ");
    private final JButton cancelButton = new JButton("Cancel duel");

    private Supplier<DuelState> duelStateSupplier = () -> DuelState.IDLE;
    private Runnable cancelAction = () -> {};

    @Inject
    public RankedDuelsPanel(ApiClient api, RankedDuelsConfig config, ScheduledExecutorService executor)
    {
        super(false); // manage our own borders
        this.api = api;
        this.config = config;
        this.executor = executor;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(10, 10, 10, 10));

        // ---- Header: title + refresh ----
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARK_GRAY_COLOR);
        header.setBorder(new EmptyBorder(0, 0, 8, 0));

        JLabel title = new JLabel("Ranked Duels");
        title.setFont(FontManager.getRunescapeBoldFont().deriveFont(17f));
        title.setForeground(GOLD);
        header.add(title, BorderLayout.WEST);

        JButton refresh = new JButton("\u21bb");
        refresh.setToolTipText("Refresh");
        refresh.setFocusPainted(false);
        refresh.setMargin(new Insets(2, 8, 2, 8));
        refresh.addActionListener(e -> refreshAsync());
        header.add(refresh, BorderLayout.EAST);
        add(header, BorderLayout.NORTH);

        // ---- Content: north-anchored column inside a v-only scroll ----
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel anchor = new JPanel(new BorderLayout());
        anchor.setBackground(ColorScheme.DARK_GRAY_COLOR);
        anchor.add(content, BorderLayout.NORTH);

        JScrollPane scroll = new JScrollPane(anchor);
        scroll.setBorder(null);
        scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setVerticalScrollBarPolicy(JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED);
        scroll.getVerticalScrollBar().setPreferredSize(new Dimension(7, 0));
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        add(scroll, BorderLayout.CENTER);

        // ---- Footer: cancel (contextual) + status line ----
        JPanel footer = new JPanel(new BorderLayout());
        footer.setBackground(ColorScheme.DARK_GRAY_COLOR);
        footer.setBorder(new EmptyBorder(8, 0, 0, 0));

        cancelButton.setBackground(new Color(0x5A, 0x1C, 0x16));
        cancelButton.setForeground(Color.WHITE);
        cancelButton.setFocusPainted(false);
        cancelButton.setVisible(false);
        cancelButton.addActionListener(e -> {
            cancelAction.run();
            // Give the state machine a moment, then re-check visibility.
            executor.schedule(
                () -> SwingUtilities.invokeLater(this::updateCancelButton),
                600, java.util.concurrent.TimeUnit.MILLISECONDS);
        });
        footer.add(cancelButton, BorderLayout.NORTH);

        statusLabel.setForeground(DIM);
        statusLabel.setFont(FontManager.getRunescapeSmallFont());
        footer.add(statusLabel, BorderLayout.SOUTH);
        add(footer, BorderLayout.SOUTH);

        showNotLinked();
    }

    public void setDuelStateSupplier(Supplier<DuelState> supplier)
    {
        this.duelStateSupplier = supplier;
    }

    public void setCancelAction(Runnable action)
    {
        this.cancelAction = action;
    }

    private void updateCancelButton()
    {
        DuelState state = duelStateSupplier.get();
        boolean active = state != DuelState.IDLE;
        cancelButton.setVisible(active);
        switch (state)
        {
            case CHALLENGE_SENT:
                cancelButton.setText("Cancel challenge");
                break;
            case CHALLENGE_RECEIVED:
                cancelButton.setText("Decline challenge");
                break;
            case PENDING_FIGHT:
            case FIGHTING:
                cancelButton.setText("Void duel");
                break;
            default:
                break;
        }
        revalidate();
        repaint();
    }

    /** Call when the panel is opened or a duel state changes. Any thread. */
    public void refreshAsync()
    {
        SwingUtilities.invokeLater(this::updateCancelButton);
        if (!api.isLinked())
        {
            SwingUtilities.invokeLater(this::showNotLinked);
            return;
        }
        SwingUtilities.invokeLater(() -> statusLabel.setText("Loading..."));
        executor.execute(() -> {
            JsonObject me = api.getMe();
            SwingUtilities.invokeLater(() -> {
                if (me == null)
                {
                    statusLabel.setText("Could not reach the ladder server.");
                    return;
                }
                render(me);
                statusLabel.setText(" ");
            });
        });
    }

    private void showNotLinked()
    {
        content.removeAll();
        JTextArea msg = new JTextArea(
            "Log into OSRS and you'll be placed on the ladder automatically.\n\n" +
            "Optional: register at rankedduel.com and paste your link code in " +
            "the plugin settings to claim your profile.");
        msg.setEditable(false);
        msg.setLineWrap(true);
        msg.setWrapStyleWord(true);
        msg.setBackground(ColorScheme.DARK_GRAY_COLOR);
        msg.setForeground(Color.WHITE);
        msg.setFont(FontManager.getRunescapeSmallFont());
        msg.setBorder(new EmptyBorder(8, 2, 8, 2));
        content.add(msg);
        content.revalidate();
        content.repaint();
        statusLabel.setText(" ");
    }

    private void render(JsonObject me)
    {
        content.removeAll();

        // ---- Identity card: name, rating, tier / rank / peak ----
        JPanel identity = card();
        identity.add(centered(label(me.get("name").getAsString(),
            FontManager.getRunescapeBoldFont().deriveFont(15f), Color.WHITE)));
        identity.add(Box.createVerticalStrut(2));
        identity.add(centered(label(String.valueOf(me.get("rating").getAsInt()),
            FontManager.getRunescapeBoldFont().deriveFont(26f), HITSPLAT)));

        String tierName = me.has("tier") && me.get("tier").isJsonObject()
            ? me.getAsJsonObject("tier").get("name").getAsString() : null;
        if (tierName != null)
        {
            identity.add(centered(label(tierName.toUpperCase(),
                FontManager.getRunescapeSmallFont(), GOLD)));
        }
        identity.add(Box.createVerticalStrut(4));
        // Split sub info over lines: avoids the old one-line overflow
        identity.add(centered(label("Rank #" + me.get("global_rank").getAsInt()
                + "   Peak " + me.get("peak_rating").getAsInt(),
            FontManager.getRunescapeSmallFont(), DIM)));
        if (me.get("provisional").getAsBoolean())
        {
            identity.add(centered(label("provisional rating",
                FontManager.getRunescapeSmallFont(), DIM)));
        }
        content.add(identity);
        content.add(Box.createVerticalStrut(8));

        // ---- Duels record ----
        content.add(statRow(new String[][] {
            {"Wins", String.valueOf(me.get("wins").getAsInt())},
            {"Losses", String.valueOf(me.get("losses").getAsInt())},
        }, new Color[] {WIN, LOSS}));
        content.add(Box.createVerticalStrut(8));

        // ---- PK record ----
        if (me.has("pk_kills"))
        {
            int kills = me.get("pk_kills").getAsInt();
            int deaths = me.has("pk_deaths") ? me.get("pk_deaths").getAsInt() : 0;
            String kd = deaths > 0 ? String.format("%.2f", (double) kills / deaths) : String.valueOf(kills);
            content.add(statRow(new String[][] {
                {"PK Kills", String.valueOf(kills)},
                {"Deaths", String.valueOf(deaths)},
                {"K/D", kd},
            }, new Color[] {WIN, LOSS, GOLD}));
            content.add(Box.createVerticalStrut(12));
        }

        // ---- Recent duels ----
        JLabel recentTitle = label("RECENT DUELS", FontManager.getRunescapeSmallFont(), GOLD);
        recentTitle.setBorder(new EmptyBorder(0, 2, 6, 0));
        recentTitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        content.add(recentTitle);

        JsonArray recent = me.getAsJsonArray("recent_duels");
        if (recent == null || recent.size() == 0)
        {
            JLabel none = label("No finished duels yet.", FontManager.getRunescapeSmallFont(), DIM);
            none.setAlignmentX(Component.LEFT_ALIGNMENT);
            content.add(none);
        }
        else
        {
            for (var el : recent)
            {
                JsonObject d = el.getAsJsonObject();
                boolean won = d.get("won").getAsBoolean();
                double delta = d.get("rating_change").getAsDouble();

                JPanel row = new JPanel(new BorderLayout(6, 0));
                row.setBackground(CARD);
                row.setBorder(new CompoundBorder(
                    new MatteBorder(0, 2, 0, 0, won ? WIN : LOSS),
                    new EmptyBorder(5, 8, 5, 8)));
                row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
                row.setAlignmentX(Component.LEFT_ALIGNMENT);

                JLabel opp = label(d.get("opponent").getAsString(),
                    FontManager.getRunescapeSmallFont(), Color.WHITE);
                row.add(opp, BorderLayout.CENTER);

                JLabel deltaLabel = label((delta >= 0 ? "+" : "") + String.format("%.1f", delta),
                    FontManager.getRunescapeSmallFont(), delta >= 0 ? WIN : LOSS);
                row.add(deltaLabel, BorderLayout.EAST);

                content.add(row);
                content.add(Box.createVerticalStrut(4));
            }
        }

        updateCancelButton();
        content.revalidate();
        content.repaint();
    }

    // ------------------------------------------------------------------
    // Small UI helpers
    // ------------------------------------------------------------------
    private JPanel card()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(CARD);
        panel.setBorder(new CompoundBorder(
            new MatteBorder(1, 1, 1, 1, CARD_EDGE),
            new EmptyBorder(10, 10, 10, 10)));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        return panel;
    }

    private JPanel statRow(String[][] labelValues, Color[] colors)
    {
        JPanel row = new JPanel(new GridLayout(1, labelValues.length, 6, 0));
        row.setBackground(ColorScheme.DARK_GRAY_COLOR);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        for (int i = 0; i < labelValues.length; i++)
        {
            JPanel cell = new JPanel();
            cell.setLayout(new BoxLayout(cell, BoxLayout.Y_AXIS));
            cell.setBackground(CARD);
            cell.setBorder(new CompoundBorder(
                new MatteBorder(1, 1, 1, 1, CARD_EDGE),
                new EmptyBorder(8, 4, 8, 4)));
            cell.add(centered(label(labelValues[i][1],
                FontManager.getRunescapeBoldFont().deriveFont(16f), colors[i])));
            cell.add(centered(label(labelValues[i][0],
                FontManager.getRunescapeSmallFont(), DIM)));
            row.add(cell);
        }
        return row;
    }

    private JLabel label(String text, Font font, Color color)
    {
        JLabel l = new JLabel(text);
        l.setFont(font);
        l.setForeground(color);
        return l;
    }

    private Component centered(JLabel l)
    {
        l.setAlignmentX(Component.CENTER_ALIGNMENT);
        JPanel wrap = new JPanel();
        wrap.setLayout(new BoxLayout(wrap, BoxLayout.X_AXIS));
        wrap.setBackground(CARD);
        wrap.add(Box.createHorizontalGlue());
        wrap.add(l);
        wrap.add(Box.createHorizontalGlue());
        wrap.setAlignmentX(Component.LEFT_ALIGNMENT);
        return wrap;
    }
}

package com.rankedduels.ui;

import com.rankedduels.DuelState;
import com.rankedduels.RankedDuelsPlugin;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import javax.inject.Inject;
import java.awt.*;
import java.time.Duration;
import java.time.Instant;

/**
 * Big "RANKED [star] DUELS" banner drawn top-center while a ranked duel is
 * live: gold serif lettering with a shadow, red spark between the words,
 * opponent name and fight timer underneath.
 */
public class FightBannerOverlay extends Overlay
{
    private static final Color GOLD = new Color(0xE0, 0xCE, 0xA4);
    private static final Color GOLD_DIM = new Color(0xA9, 0x9C, 0x78);
    private static final Color RED = new Color(0xC0, 0x28, 0x1C);
    private static final Color SHADOW = new Color(0, 0, 0, 190);

    private static final Font TITLE_FONT = new Font(Font.SERIF, Font.BOLD, 26);
    private static final Font SUB_FONT = new Font(Font.SERIF, Font.PLAIN, 15);

    private final RankedDuelsPlugin plugin;

    @Inject
    public FightBannerOverlay(RankedDuelsPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        DuelState state = plugin.getState();
        if (state != DuelState.FIGHTING && state != DuelState.PENDING_FIGHT)
        {
            return null;
        }

        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        String left = "RANKED";
        String right = "DUELS";
        String stakes = (plugin.getWinDelta() != 0 || plugin.getLossDelta() != 0)
            ? "  \u2022  " + RankedDuelsPlugin.formatDelta(plugin.getWinDelta())
                + " / " + RankedDuelsPlugin.formatDelta(plugin.getLossDelta())
            : "";
        String sub;
        if (state == DuelState.FIGHTING)
        {
            long secs = plugin.getFightStartedAt() != null
                ? Duration.between(plugin.getFightStartedAt(), Instant.now()).getSeconds()
                : 0;
            sub = "vs " + plugin.getOpponentName() + "  \u2022  " + secs + "s" + stakes;
        }
        else
        {
            sub = "vs " + plugin.getOpponentName() + stakes + "  \u2022  first hit starts the duel";
        }

        g.setFont(TITLE_FONT);
        FontMetrics fmTitle = g.getFontMetrics();
        int starGap = 14;
        int starSize = 12;
        int titleWidth = fmTitle.stringWidth(left) + starGap * 2 + starSize + fmTitle.stringWidth(right);

        g.setFont(SUB_FONT);
        FontMetrics fmSub = g.getFontMetrics();
        int subWidth = fmSub.stringWidth(sub);

        int width = Math.max(titleWidth, subWidth) + 24;
        int titleY = fmTitle.getAscent() + 6;
        int subY = titleY + fmSub.getHeight() + 8;
        int height = subY + 8;

        // Title with letter-spacing feel via tracking-lite: draw as two words
        int x = (width - titleWidth) / 2;
        g.setFont(TITLE_FONT);
        drawShadowed(g, left, x, titleY, GOLD);
        int starX = x + fmTitle.stringWidth(left) + starGap;
        int starY = titleY - fmTitle.getAscent() / 2;
        drawSpark(g, starX + starSize / 2, starY, starSize);
        drawShadowed(g, right, starX + starSize + starGap, titleY, GOLD);

        // Subtitle
        g.setFont(SUB_FONT);
        drawShadowed(g, sub, (width - subWidth) / 2, subY, GOLD_DIM);

        return new Dimension(width, height);
    }

    private void drawShadowed(Graphics2D g, String text, int x, int y, Color color)
    {
        g.setColor(SHADOW);
        g.drawString(text, x + 1, y + 2);
        g.setColor(color);
        g.drawString(text, x, y);
    }

    /** Four-pointed spark, like the one in the logo. */
    private void drawSpark(Graphics2D g, int cx, int cy, int size)
    {
        int r = size / 2;
        int rIn = Math.max(2, size / 6);
        Polygon p = new Polygon();
        p.addPoint(cx, cy - r);
        p.addPoint(cx + rIn, cy - rIn);
        p.addPoint(cx + r, cy);
        p.addPoint(cx + rIn, cy + rIn);
        p.addPoint(cx, cy + r);
        p.addPoint(cx - rIn, cy + rIn);
        p.addPoint(cx - r, cy);
        p.addPoint(cx - rIn, cy - rIn);
        g.setColor(SHADOW);
        g.translate(1, 2);
        g.fillPolygon(p);
        g.translate(-1, -2);
        g.setColor(RED);
        g.fillPolygon(p);
    }
}

package com.rankedduels.api;

import lombok.AllArgsConstructor;
import lombok.Getter;

@Getter
@AllArgsConstructor
public class ChallengeInfo
{
    private final long challengeId;
    private final String challengerName;
    private final int challengerRating;
    private final int world;
    private final double winDelta;   // rating gained on win
    private final double lossDelta;  // rating lost on loss (negative)
}

package com.rankedduels.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.rankedduels.RankedDuelsConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import okhttp3.*;

import com.rankedduels.RankedDuelsPlugin;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Map;

/**
 * Talks to the WordPress REST API (ranked-duels-api plugin).
 * Every request carries the account hash + bearer token issued during linking.
 * All calls are blocking - always invoke from the plugin's executor, never the client thread.
 */
@Slf4j
@Singleton
public class ApiClient
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    @Inject private OkHttpClient http;
    @Inject private Gson gson;
    @Inject private Client client;
    @Inject private RankedDuelsConfig config;
    @Inject private ConfigManager configManager;

    /** Set when the server rejects this plugin version (HTTP 426). */
    private volatile boolean outdated;

    /**
     * Stable account identity, cached from the client thread each tick.
     * Jagex accounts: the numeric account hash. Legacy accounts return -1
     * from getAccountHash(), which would make every legacy player collide
     * into one ladder profile - so those get a SHA-256 of their login name.
     */
    private volatile String accountId;

    /** Called from the plugin on the client thread (GameTick). */
    public void updateIdentity(long accountHash, String loginName)
    {
        if (accountHash != -1L)
        {
            accountId = String.valueOf(accountHash);
        }
        else if (loginName != null && !loginName.isEmpty())
        {
            accountId = "legacy_" + sha256("rankedduels:" + loginName.toLowerCase().trim());
        }
    }

    public void clearIdentity()
    {
        accountId = null;
    }

    private static String sha256(String input)
    {
        try
        {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            byte[] digest = md.digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 12; i++) // 24 hex chars is plenty; column is 32
            {
                sb.append(String.format("%02x", digest[i]));
            }
            return sb.toString();
        }
        catch (Exception e)
        {
            return "legacy_unknown";
        }
    }

    /** Per-account token storage: two accounts on one PC no longer collide. */
    private String tokenKey()
    {
        return "apiToken-" + accountId;
    }

    private String storedToken()
    {
        if (accountId == null)
        {
            return null;
        }
        String token = configManager.getConfiguration("rankedduels", tokenKey());
        if (token == null || token.isEmpty())
        {
            // One-time migration from the old single-token config key.
            String legacy = config.apiToken();
            if (legacy != null && !legacy.isEmpty())
            {
                configManager.setConfiguration("rankedduels", tokenKey(), legacy);
                configManager.setConfiguration("rankedduels", "apiToken", "");
                return legacy;
            }
            return null;
        }
        return token;
    }

    private void storeToken(String token)
    {
        if (accountId != null)
        {
            configManager.setConfiguration("rankedduels", tokenKey(), token);
        }
    }

    public boolean isOutdated()
    {
        return outdated;
    }

    public boolean isLinked()
    {
        String token = storedToken();
        return token != null && !token.isEmpty();
    }

    /**
     * Exchange the one-time link code (shown on the user's website profile)
     * for a long-lived API token bound to this account hash.
     */
    /**
     * Zero-friction onboarding: register this game account on the ladder
     * with no website account. Returns true when a token was issued.
     */
    public boolean autoRegister(String displayName)
    {
        if (accountId == null)
        {
            return false;
        }
        JsonObject body = new JsonObject();
        body.addProperty("account_hash", accountId);
        body.addProperty("display_name", displayName == null ? "" : displayName);

        JsonObject resp = post("/register", body, false);
        if (resp != null && resp.has("token"))
        {
            storeToken(resp.get("token").getAsString());
            return true;
        }
        return false;
    }

    public static final int LINK_OK = 1;
    public static final int LINK_FAILED = 0;
    public static final int LINK_INVALID_CODE = -1;

    public int linkAccount(String displayName)
    {
        if (accountId == null)
        {
            return LINK_FAILED;
        }
        JsonObject body = new JsonObject();
        body.addProperty("link_code", config.linkCode());
        body.addProperty("account_hash", accountId);
        body.addProperty("display_name", displayName == null ? "" : displayName);

        Request.Builder rb = new Request.Builder()
            .url(config.apiBaseUrl() + "/link")
            .post(RequestBody.create(JSON, gson.toJson(body)));
        rb.header("X-Plugin-Version", RankedDuelsPlugin.VERSION);
        try (Response response = http.newCall(rb.build()).execute())
        {
            if (response.code() == 404)
            {
                return LINK_INVALID_CODE; // code already used or wrong
            }
            if (!response.isSuccessful() || response.body() == null)
            {
                return LINK_FAILED;
            }
            JsonObject resp = gson.fromJson(response.body().string(), JsonObject.class);
            if (resp != null && resp.has("token"))
            {
                storeToken(resp.get("token").getAsString());
                return LINK_OK;
            }
            return LINK_FAILED;
        }
        catch (Exception e)
        {
            log.debug("link failed", e);
            return LINK_FAILED;
        }
    }

    /**
     * Result of sending a challenge. If the target had already challenged
     * us, the server treats the crossing challenge as an acceptance and
     * returns a live duel id instead ("mutual").
     */
    public static class ChallengeResult
    {
        public long duelId = -1;   // >0 when mutual: the duel is already on
        public double winDelta;
        public double lossDelta;
    }

    public ChallengeResult sendChallenge(String targetName, int world, int worldLocation)
    {
        JsonObject body = new JsonObject();
        body.addProperty("target_name", targetName);
        body.addProperty("world", world);
        body.addProperty("world_location", worldLocation);
        JsonObject resp = post("/challenge", body, true);
        if (resp == null || (!resp.has("challenge_id") && !resp.has("duel_id")))
        {
            return null;
        }
        ChallengeResult result = new ChallengeResult();
        if (resp.has("duel_id"))
        {
            result.duelId = resp.get("duel_id").getAsLong();
        }
        result.winDelta = resp.has("win_delta") ? resp.get("win_delta").getAsDouble() : 0;
        result.lossDelta = resp.has("loss_delta") ? resp.get("loss_delta").getAsDouble() : 0;
        return result;
    }

    /** Accept or decline an incoming challenge. Returns duel id on accept, -1 otherwise. */
    public long respondToChallenge(long challengeId, boolean accept, int world, int worldLocation)
    {
        JsonObject body = new JsonObject();
        body.addProperty("challenge_id", challengeId);
        body.addProperty("accept", accept);
        body.addProperty("world", world);
        body.addProperty("world_location", worldLocation);
        JsonObject resp = post("/challenge/respond", body, true);
        if (accept && resp != null && resp.has("duel_id"))
        {
            return resp.get("duel_id").getAsLong();
        }
        return -1;
    }

    public boolean cancelChallenge()
    {
        return post("/challenge/cancel", new JsonObject(), true) != null;
    }

    public void reportFightStarted(long duelId, int world, Map<String, Integer> myGear, Map<String, Integer> oppGear)
    {
        JsonObject body = new JsonObject();
        body.addProperty("duel_id", duelId);
        body.addProperty("world", world);
        body.add("my_gear", gson.toJsonTree(myGear));
        body.add("opponent_gear", gson.toJsonTree(oppGear));
        post("/duel/started", body, true);
    }

    public void reportFightFinished(long duelId, boolean won, int world,
                                    Map<String, Integer> myGear, Map<String, Integer> oppGear,
                                    int damageDealt, int damageTaken)
    {
        JsonObject body = new JsonObject();
        body.addProperty("duel_id", duelId);
        body.addProperty("won", won);
        body.addProperty("world", world);
        body.add("my_gear", gson.toJsonTree(myGear));
        body.add("opponent_gear", gson.toJsonTree(oppGear));
        body.addProperty("damage_dealt", damageDealt);
        body.addProperty("damage_taken", damageTaken);
        post("/duel/finished", body, true);
    }

    /** Raw PK tracking: type is "kill" or "death". Fire and forget. */
    public void reportPk(String type, int world)
    {
        JsonObject body = new JsonObject();
        body.addProperty("type", type);
        body.addProperty("world", world);
        post("/pk/report", body, true);
    }

    public void reportAbort(long duelId, String reason)
    {
        JsonObject body = new JsonObject();
        body.addProperty("duel_id", duelId);
        body.addProperty("reason", reason);
        post("/duel/abort", body, true);
    }

    /** Own ladder stats + recent duels, for the side panel. */
    public JsonObject getMe()
    {
        return get("/me");
    }

    /**
     * Single lightweight poll for anything the server wants to tell this client.
     * Carries the current display name so the server can heal rows that were
     * linked before the player name was available.
     */
    public PollResult poll(String displayName)
    {
        String url = config.apiBaseUrl() + "/poll";
        if (displayName != null && !displayName.isEmpty())
        {
            url += "?name=" + java.net.URLEncoder.encode(displayName, java.nio.charset.StandardCharsets.UTF_8);
        }
        Request.Builder rb = new Request.Builder().url(url).get();
        JsonObject resp = execute(rb, true);
        if (resp == null) return null;

        PollResult result = new PollResult();
        if (resp.has("incoming_challenge") && resp.get("incoming_challenge").isJsonObject())
        {
            JsonObject ch = resp.getAsJsonObject("incoming_challenge");
            result.incomingChallenge = new ChallengeInfo(
                ch.get("challenge_id").getAsLong(),
                ch.get("challenger_name").getAsString(),
                ch.has("challenger_rating") ? ch.get("challenger_rating").getAsInt() : 0,
                ch.has("world") ? ch.get("world").getAsInt() : 0,
                ch.has("win_delta") ? ch.get("win_delta").getAsDouble() : 0,
                ch.has("loss_delta") ? ch.get("loss_delta").getAsDouble() : 0
            );
        }
        result.outdated = resp.has("outdated") && resp.get("outdated").getAsBoolean();
        if (result.outdated)
        {
            outdated = true;
        }
        result.duelAccepted = resp.has("duel_accepted") && resp.get("duel_accepted").getAsBoolean();
        result.duelDeclined = resp.has("duel_declined") && resp.get("duel_declined").getAsBoolean();
        if (resp.has("duel_id"))
        {
            result.duelId = resp.get("duel_id").getAsLong();
        }
        if (resp.has("win_delta"))
        {
            result.winDelta = resp.get("win_delta").getAsDouble();
            result.lossDelta = resp.get("loss_delta").getAsDouble();
        }
        return result;
    }

    // ------------------------------------------------------------------
    private JsonObject post(String path, JsonObject body, boolean authed)
    {
        Request.Builder rb = new Request.Builder()
            .url(config.apiBaseUrl() + path)
            .post(RequestBody.create(JSON, gson.toJson(body)));
        return execute(rb, authed);
    }

    private JsonObject get(String path)
    {
        Request.Builder rb = new Request.Builder().url(config.apiBaseUrl() + path).get();
        return execute(rb, true);
    }

    private JsonObject execute(Request.Builder rb, boolean authed)
    {
        rb.header("X-Plugin-Version", RankedDuelsPlugin.VERSION);
        if (authed)
        {
            String token = storedToken();
            if (token == null || accountId == null)
            {
                return null; // not linked for this account yet
            }
            rb.header("Authorization", "Bearer " + token);
            rb.header("X-Account-Hash", accountId);
        }
        try (Response response = http.newCall(rb.build()).execute())
        {
            if (response.code() == 426)
            {
                outdated = true;
                log.info("Server requires a newer plugin version");
                return null;
            }
            if (!response.isSuccessful() || response.body() == null)
            {
                log.debug("API call failed: {} {}", response.code(), response.message());
                return null;
            }
            // Be lenient: some responses (e.g. empty PHP arrays) arrive as
            // JSON arrays. Treat anything that isn't an object as "no data".
            com.google.gson.JsonElement el = new JsonParser().parse(response.body().string());
            return el != null && el.isJsonObject() ? el.getAsJsonObject() : new JsonObject();
        }
        catch (IOException e)
        {
            log.debug("API call error", e);
            return null;
        }
    }

    public static class PollResult
    {
        public ChallengeInfo incomingChallenge;
        public boolean duelAccepted;
        public boolean duelDeclined;
        public long duelId;
        public double winDelta;
        public double lossDelta;
        public boolean outdated;
    }
}

